param([string]$OutPath="F:\descargasf\prisma-mobile-upload-key.jks",[string]$Alias="prisma_upload")
Set-StrictMode -Version Latest; $ErrorActionPreference="Stop"; $Keytool=(Get-Command keytool -ErrorAction Stop).Source; if(Test-Path -LiteralPath $OutPath){throw "Keystore exists: $OutPath"}; if(-not $env:PRISMA_ANDROID_KEYSTORE_PASSWORD){throw "Set PRISMA_ANDROID_KEYSTORE_PASSWORD"}; if(-not $env:PRISMA_ANDROID_KEY_PASSWORD){throw "Set PRISMA_ANDROID_KEY_PASSWORD"}; New-Item -ItemType Directory -Force -Path (Split-Path -Parent $OutPath)|Out-Null; & $Keytool -genkeypair -v -keystore $OutPath -storetype JKS -alias $Alias -keyalg RSA -keysize 2048 -validity 9125 -storepass $env:PRISMA_ANDROID_KEYSTORE_PASSWORD -keypass $env:PRISMA_ANDROID_KEY_PASSWORD -dname "CN=PRISMA App Mobile, OU=Terminal de Venta, O=PRISMA, L=Mexico City, S=CDMX, C=MX"; & $Keytool -list -v -keystore $OutPath -alias $Alias -storepass $env:PRISMA_ANDROID_KEYSTORE_PASSWORD | Select-String -Pattern "SHA256"
